/* Beta — E-Way Bills (Sales Order → E-Way Bill): every e-way bill in one list, wherever it was made —
 * on a Delivery Challan (generated by the E-Way Helper or typed in), read from a Sales Bill PDF, or on a Return Note /
 * Return to Vendor. One line per e-way bill number (a DC and its bill with the same number are one line).
 * Select a line → Print E-Way Bill (the portal PDF, exactly as the portal prints it) · Upload / Replace the portal PDF. */
import React, { useEffect, useMemo, useRef, useState } from 'react';
import axios from 'axios';
import { useCompany } from '../../context/CompanyContext';
import { Svg } from '../../components/ui/Icon';
import { CSS as SALES_CSS, useClearSel } from './BetaSales';
import { printPortalEwb, uploadPortalPdf, billOfDc, dcsOfBill } from './BetaDCPrint';
import { printReturnPortal, uploadReturnPdf } from './ReturnPrint';

const amt = v => (Number(v) || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const MON = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
/* "29-Oct-26 11:59 PM" / "29/10/2026 11:59:00 PM" / ISO → Date (end of that day when no time) */
const parseWhen = s => {
  const t = String(s || '').trim(); if (!t) return null;
  let m = t.match(/^(\d{1,2})[-/ ]([A-Za-z]{3})[A-Za-z]*[-/ ](\d{2,4})(?:\s+(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?)?/i);
  let d = null;
  if (m) d = { dd: +m[1], mm: MON[m[2].toLowerCase()], yy: +m[3], h: m[4], mi: m[5], ap: m[6] };
  else if ((m = t.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})(?:\s+(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?)?/i))) d = { dd: +m[1], mm: +m[2] - 1, yy: +m[3], h: m[4], mi: m[5], ap: m[6] };
  if (!d) { const x = new Date(t); return isNaN(x) ? null : x; }
  if (d.mm == null || isNaN(d.mm)) return null;
  const yy = d.yy < 100 ? 2000 + d.yy : d.yy;
  let h = d.h != null ? +d.h : 23; const mi = d.mi != null ? +d.mi : 59;
  if (d.ap) { if (/pm/i.test(d.ap) && h < 12) h += 12; if (/am/i.test(d.ap) && h === 12) h = 0; }
  const x = new Date(yy, d.mm, d.dd, h, mi);
  return isNaN(x) ? null : x;
};
const DATE_FMT = new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: '2-digit' });
const fdate = v => { if (!v) return ''; const x = new Date(v); return isNaN(x) ? String(v) : DATE_FMT.format(x); };
/* validity: in force / ends within a day / expired */
const stateOf = valid => {
  const d = parseWhen(valid); if (!d) return ['—', '#98A2B3', 'No valid-upto date'];
  const ms = d - Date.now();
  if (ms < 0) return ['Expired', '#B42318', 'The validity is over'];
  if (ms < 24 * 3600e3) return ['Ends today', '#B54708', 'Ends within 24 hours'];
  return ['Valid', '#067647', 'In force'];
};

const EXTRA_CSS = `
.ewx td { white-space:normal; overflow-wrap:anywhere; line-height:1.35; } .ewx td.d { white-space:nowrap; }
.ewx .sm { display:block; font-size:11px; color:#667085; } .ewx .b { font-weight:700; }
.ewx tbody tr:hover td { background:#F0F7F8; }
.ewx tbody tr.sel td { background:#D4EBEE !important; } .ewx tbody tr.sel td:first-child { box-shadow:inset 3px 0 0 #03444f; }
.ew-pill { display:inline-block; padding:1px 8px; border-radius:99px; font-size:11px; font-weight:600; color:#fff; white-space:nowrap; }
.ew-doc { display:inline-block; margin:0 4px 2px 0; padding:0 6px; border:1px solid #C9DCDE; border-radius:4px; font-size:11.5px; white-space:nowrap; }
.ew-doc i { font-style:normal; color:#667085; margin-right:3px; }
.ew-pdf { font-size:11.5px; font-weight:600; } .ew-pdf.ok { color:#067647; } .ew-pdf.no { color:#B54708; }
.sb-chk { display:flex; align-items:center; gap:6px; padding:0 12px; font-size:12.5px; white-space:nowrap; border-right:1px solid #C9DCDE; cursor:pointer; }
`;

export default function BetaEway() {
  const { selectedCompany } = useCompany() || {};
  const companyId = selectedCompany?.companyId;
  const [dcs, setDcs] = useState(null);
  const [bills, setBills] = useState([]);
  const [rets, setRets] = useState([]);
  const [reload, setReload] = useState(0);
  const [q, setQ] = useState('');
  const [noPdf, setNoPdf] = useState(false);
  const [selKey, setSelKey] = useState(null);
  const [note, setNote] = useState(null);
  const [busy, setBusy] = useState(false);
  const fileIn = useRef(null);

  useEffect(() => {
    if (!companyId) return;
    const p = { params: { companyId } };
    axios.get('/api/delivery-challans', p).then(r => setDcs(Array.isArray(r.data) ? r.data.filter(d => d && d.status !== 'deleted') : [])).catch(() => setDcs([]));
    axios.get('/api/bills', { params: { companyId, type: 'sales' } }).then(r => setBills(Array.isArray(r.data) ? r.data.filter(b => b && b.type !== 'purchase' && b.status !== 'deleted') : [])).catch(() => setBills([]));
    axios.get('/api/returns', p).then(r => setRets(Array.isArray(r.data) ? r.data : [])).catch(() => setRets([]));
  }, [companyId, reload]);

  /* one line per e-way bill number */
  const rows = useMemo(() => {
    const by = new Map();
    const line = no => { const k = String(no).replace(/\s+/g, ''); if (!by.has(k)) by.set(k, { key: k, no: k, docs: [], dc: null, ret: null, bill: null }); return by.get(k); };
    (dcs || []).forEach(dc => {
      if (!String(dc.ewayBillNo || '').trim()) return;
      const l = line(dc.ewayBillNo), b = billOfDc(dc, bills);
      l.dc = l.dc || dc;
      l.docs.push({ t: 'DC', no: dc.dcNo || dc.dcId, date: dc.dcDate });
      if (b && !l.docs.some(x => x.t === 'Bill' && x.no === (b.billNo || b.billId))) { l.docs.push({ t: 'Bill', no: b.billNo || b.billId, date: b.billDate }); l.bill = l.bill || b; }
      l.party = l.party || dc.customerName || dc.billingName || '';
      l.to = l.to || [dc.shippingName && dc.shippingName !== l.party ? dc.shippingName : '', dc.shippingCity].filter(Boolean).join(', ');
      l.vehicle = l.vehicle || dc.vehicleNo || '';
      l.gen = l.gen || dc.ewayGenDate || ''; l.valid = l.valid || dc.ewayValidUpto || '';
      l.value = l.value || Number(dc.grandTotal) || 0;
      l.date = l.date || dc.dcDate;
    });
    bills.forEach(b => {
      if (!String(b.ewayBillNo || '').trim()) return;
      const l = line(b.ewayBillNo);
      if (!l.docs.some(x => x.t === 'Bill' && x.no === (b.billNo || b.billId))) l.docs.push({ t: 'Bill', no: b.billNo || b.billId, date: b.billDate });
      l.bill = l.bill || b;
      // e-way number only on the bill (read from its PDF): its delivery challans carry the portal PDF
      if (!l.dc && !l.billDcs) {
        const ds = dcsOfBill(b, dcs || []);
        if (ds.length) { l.billDcs = ds; ds.forEach(d => l.docs.push({ t: 'DC', no: d.dcNo || d.dcId, date: d.dcDate })); }
      }
      l.party = l.party || b.partyName || b.billToName || '';
      l.vehicle = l.vehicle || b.vehicleNo || '';
      l.gen = l.gen || b.ewayGenDate || ''; l.valid = l.valid || b.ewayValidUpto || '';
      l.value = l.value || Number(b.grandTotal) || 0;
      l.date = l.date || b.billDate;
    });
    rets.forEach(r => {
      if (!String(r.ewayBillNo || '').trim()) return;
      const l = line(r.ewayBillNo), client = r.kind === 'client';
      l.ret = l.ret || r;
      l.docs.push({ t: client ? 'Return Note' : 'Return to Vendor', no: r.returnNo || r.returnId, date: r.date });
      l.party = l.party || (client ? r.fromParty?.name : r.toParty?.name) || r.customerName || r.vendorName || '';
      l.vehicle = l.vehicle || r.vehicleNo || '';
      l.gen = l.gen || r.ewayGenDate || ''; l.valid = l.valid || r.ewayValidUpto || '';
      l.value = l.value || Number(r.grandTotal || r.totalValue) || 0;
      l.date = l.date || r.date;
    });
    return [...by.values()].map(l => {
      // the portal PDF: kept on the DC (or the Return Note); for a bill alone, on any of its DCs with this number
      const bdc = (l.billDcs || []).find(d => d.ewayPdf);
      const pdfOn = l.dc?.ewayPdf ? { kind: 'dc', doc: l.dc } : bdc ? { kind: 'dc', doc: { ...bdc, ewayBillNo: bdc.ewayBillNo || l.no } } : l.ret?.ewayPdf ? { kind: 'ret', doc: l.ret } : null;
      const upDc = l.dc || bdc || (l.billDcs || [])[0];
      return { ...l, pdfOn, uploadTo: upDc ? { kind: 'dc', doc: upDc } : l.ret ? { kind: 'ret', doc: l.ret } : null, st: stateOf(l.valid), when: parseWhen(l.gen) || (l.date ? new Date(l.date) : null) };
    }).sort((a, b) => (b.when ? +b.when : 0) - (a.when ? +a.when : 0));
  }, [dcs, bills, rets]);

  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  const list = rows.filter(r => (!noPdf || !r.pdfOn)
    && (!words.length || words.every(w => `${r.no} ${r.party} ${r.to} ${r.vehicle} ${r.docs.map(d => `${d.t} ${d.no}`).join(' ')} ${r.st[0]}`.toLowerCase().includes(w))));
  const sel = list.find(r => r.key === selKey) || null;
  useClearSel(selKey, setSelKey, '.sb-t tbody tr, .sb-tools, .cpv-ov');

  const printEwb = async r => {
    setNote(null);
    try {
      if (r.pdfOn.kind === 'dc') await printPortalEwb({ dc: r.pdfOn.doc, company: selectedCompany });
      else await printReturnPortal({ r: r.pdfOn.doc, companyId });
    } catch { setNote({ err: true, text: `Could not open the portal PDF of e-way bill ${r.no}.` }); }
  };
  const upload = async (r, file) => {
    setBusy(true); setNote(null);
    try {
      if (r.uploadTo.kind === 'dc') await uploadPortalPdf(r.uploadTo.doc, file);
      else await uploadReturnPdf(r.uploadTo.doc, file, companyId);
      setNote({ text: `Portal PDF saved with e-way bill ${r.no}.` }); setReload(x => x + 1);
    } catch (e) { setNote({ err: true, text: e.response?.data?.error || e.message || 'Could not save the PDF.' }); }
    finally { setBusy(false); }
  };
  const missing = rows.filter(r => !r.pdfOn).length;

  return (
    <div className="sb">
      <style>{SALES_CSS + EXTRA_CSS}</style>
      <div className="sb-tabs" role="tablist">
        <button type="button" role="tab" aria-selected="true" className="sb-tab on">E-Way Bills{dcs && <span className="n">{rows.length}</span>}</button>
        <input className="sb-search" value={q} onChange={e => setQ(e.target.value)} placeholder="Search e-way no., DC, bill, client, vehicle…" aria-label="Search e-way bills" />
        <label className="sb-chk" title="E-way bills whose portal PDF is not saved yet">
          <input type="checkbox" checked={noPdf} onChange={e => setNoPdf(e.target.checked)} />PDF not saved <small>{missing}</small>
        </label>
        <div className="sb-tools">
          <span className="sb-picked">{sel ? <>Selected: <b>{sel.no}</b></> : 'Click an e-way bill to select'}</span>
          <button type="button" className="sb-tbtn" disabled={!sel || !sel.pdfOn} title={sel && !sel.pdfOn ? 'The portal PDF is not saved yet — upload it first' : 'The e-way bill exactly as the portal prints it'} onClick={() => printEwb(sel)}><Svg name="file" size={13} />Print E-Way Bill</button>
          <button type="button" className="sb-tbtn" disabled={!sel || !sel.uploadTo || busy} title={sel && !sel.uploadTo ? 'This e-way bill is only on a sales bill — upload its PDF on the delivery challan' : 'Upload the PDF saved from the e-way portal'} onClick={() => fileIn.current?.click()}><Svg name="plus" size={13} />{busy ? 'Saving…' : sel?.pdfOn ? 'Replace PDF' : 'Upload PDF'}</button>
        </div>
      </div>
      <input ref={fileIn} type="file" accept="application/pdf,.pdf" hidden onChange={e => { const f = e.target.files && e.target.files[0]; e.target.value = ''; if (f && sel) upload(sel, f); }} />
      {note && <div className="sb-note" role="status" style={note.err ? { color: '#B42318' } : undefined}>{note.text}<button type="button" onClick={() => setNote(null)} aria-label="Dismiss">×</button></div>}
      <div className="sb-list">
        <table className="sb-t ewx">
          <colgroup>{[3, 11, 20, 18, 10, 10, 10, 8, 10].map((w, i) => <col key={i} style={{ width: `${w}%` }} />)}</colgroup>
          <thead><tr><th className="r">Sr</th><th>E-Way Bill No.</th><th>DC / Bill / Return</th><th>Client / Party</th><th>Vehicle</th><th>Generated</th><th>Valid Upto</th><th className="r">Value ₹</th><th>Portal PDF</th></tr></thead>
          <tbody>
            {dcs === null ? <tr><td colSpan={9} className="sb-empty">Loading…</td></tr>
              : !list.length ? <tr><td colSpan={9} className="sb-empty">{q || noPdf ? 'Nothing matches.' : 'No e-way bill yet — generate one on a Delivery Challan.'}</td></tr>
                : list.map((r, i) => (
                  <tr key={r.key} className={selKey === r.key ? 'sel' : ''} onClick={() => setSelKey(r.key)} onDoubleClick={() => r.pdfOn && printEwb(r)} title={r.pdfOn ? 'Click to select · double-click to print the e-way bill' : 'Click to select'} style={{ cursor: 'pointer' }}>
                    <td className="r">{i + 1}</td>
                    <td className="d"><b className="mono">{r.no}</b></td>
                    <td>{r.docs.map(d => <span key={d.t + d.no} className="ew-doc"><i>{d.t}</i>{d.no}</span>)}</td>
                    <td><span className="b">{r.party || '—'}</span>{r.to && <span className="sm">To: {r.to}</span>}</td>
                    <td className="d">{r.vehicle || '—'}</td>
                    <td className="d">{r.gen || fdate(r.date) || '—'}</td>
                    <td className="d">{r.valid || '—'}<span className="sm"><span className="ew-pill" style={{ background: r.st[1] }} title={r.st[2]}>{r.st[0]}</span></span></td>
                    <td className="r">{r.value ? amt(r.value) : '—'}</td>
                    <td>{r.pdfOn ? <span className="ew-pdf ok">✓ Saved</span> : <span className="ew-pdf no">Not saved</span>}</td>
                  </tr>
                ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
